// Originally generated by Lovable; maintained by hand since this project went
// standalone, so it is safe to edit.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { brokeredPreviewStorage } from './previewAuthStorage';
import { describeSupabaseConfig } from '@/lib/supabaseConfig';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

// A blanket 401 across every table is always configuration, never data, and
// the browser cannot see which. Saying what the build was given — the kind of
// key, never its value — turns that into a one-line diagnosis.
const config = describeSupabaseConfig(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY);
if (config.problem) {
  console.error(
    `[supabase] Configuration problem: ${config.problem}\n` +
    `  project ref: ${config.projectRef ?? '(none)'}\n` +
    `  key kind:    ${config.keyKind}\n` +
    `  key:         ${config.keyPreview}`,
  );
}

export const supabaseConfigReport = config;

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: brokeredPreviewStorage(),
    persistSession: true,
    autoRefreshToken: true,
  }
});